import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { nodeIo, type ToolIo } from '../src/tools/io.js';
import { makeClock, type TestClock } from './world.js';

// The tools' world: a real temporary folder, a fixed clock, a scripted terminal (the answers to the secret prompts, in order) and everything the
// tool printed. Keys here are generated by the tests; no key in this file is real.

export interface ToolWorld {
  dir: string;
  clock: TestClock;
  io: ToolIo;
  out: string[];
  err: string[];
  /** Every prompt text that was asked. */
  asked: string[];
  /** Everything printed or asked, as one string, for "never appears" checks. */
  everything: () => string;
  /** The writes the tool made, in order: path, mode and whether it was exclusive. */
  writes: { path: string; mode?: number | undefined; exclusive?: boolean | undefined }[];
  cleanup: () => void;
}

export function makeToolWorld(over: { secrets?: string[]; env?: Record<string, string>; fetch?: typeof fetch; start?: string } = {}): ToolWorld {
  const dir = mkdtempSync(join(tmpdir(), 'corpus-tool-'));
  const clock = makeClock(over.start ?? '2026-12-01T09:00:00Z');
  const out: string[] = [];
  const err: string[] = [];
  const asked: string[] = [];
  const writes: ToolWorld['writes'] = [];
  const answers = [...(over.secrets ?? [])];
  const real = nodeIo();
  const io: ToolIo = {
    ...real,
    clock,
    env: over.env ?? {},
    write: (path, data, options) => {
      writes.push({ path, mode: options?.mode, exclusive: options?.exclusive });
      return real.write(path, data, options);
    },
    secret: (prompt) => {
      asked.push(prompt);
      const next = answers.shift();
      return next === undefined ? Promise.reject(new Error('no terminal')) : Promise.resolve(next);
    },
    fetch: over.fetch ?? (() => Promise.reject(new Error('no network in tests'))),
    out: (l) => void out.push(l),
    err: (l) => void err.push(l),
  };
  return {
    dir,
    clock,
    io,
    out,
    err,
    asked,
    writes,
    everything: () => [...out, ...err, ...asked].join('\n'),
    cleanup: () => rmSync(dir, { recursive: true, force: true }),
  };
}
